#include "../../viewer/kms.h"
#include <assert.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
static void oracle(const struct demo_frame*f,struct dp_buffer*b){uint32_t fw=b->width,fh=(uint32_t)((uint64_t)f->height*fw/f->width);if(fh>b->height){fh=b->height;fw=(uint32_t)((uint64_t)f->width*fh/f->height);}if(!fw)fw=1;if(!fh)fh=1;uint32_t ox=(b->width-fw)/2,oy=(b->height-fh)/2;memset(b->map,0,b->bytes);for(uint32_t y=0;y<fh;y++)for(uint32_t x=0;x<fw;x++){uint32_t sy=(uint32_t)((uint64_t)y*f->height/fh),sx=(uint32_t)((uint64_t)x*f->width/fw);const uint8_t*p=f->pixels+(size_t)sy*f->stride+sx*3;uint8_t*q=b->map+(size_t)(y+oy)*b->pitch+(x+ox)*4;q[0]=p[2];q[1]=p[1];q[2]=p[0];q[3]=255;}}
int main(void){unsigned cases=0;uint32_t sizes[][4]={{1,1,3,2},{3,2,3,2},{7,5,7,5},{7,3,13,11},{13,11,7,3},{1280,720,1280,720},{256,256,1280,720},{1280,720,1920,1080}};for(unsigned k=0;k<sizeof(sizes)/sizeof(sizes[0]);k++)for(unsigned pad=0;pad<2;pad++)for(unsigned format=0;format<2;format++){struct demo_frame f={0};uint32_t*w=sizes[k];assert(!demo_frame_alloc(w[0],w[1],w[0]*3+pad*7,&f));for(size_t i=0;i<f.bytes;i++)f.pixels[i]=(uint8_t)(i*37+i/97);struct dp_buffer a={1,w[2],w[3],w[2]*4+pad*13,format?DP_ARGB8888:DP_XRGB8888,0,NULL};a.bytes=(size_t)a.pitch*a.height+pad*9;a.map=malloc(a.bytes);struct dp_buffer expected=a;expected.map=malloc(a.bytes);assert(a.map&&expected.map);memset(a.map,0xa5,a.bytes);oracle(&f,&expected);struct dp_copy_stats stats={0};assert(!dp_copy_rgb24(&f,&a,&stats)&&!memcmp(a.map,expected.map,a.bytes));assert(stats.source_bytes*4==stats.pixel_bytes*3&&stats.pixel_bytes&&stats.identity==(f.width==a.width&&f.height==a.height));if(stats.identity)assert(stats.clear_bytes==a.bytes-(uint64_t)a.width*a.height*4);struct dp_buffer bad=a;bad.pitch=a.width*4-1;assert(dp_copy_rgb24(&f,&bad,&stats)<0);bad=a;bad.format=0;assert(dp_copy_rgb24(&f,&bad,&stats)<0);bad=a;bad.map=f.pixels;assert(dp_copy_rgb24(&f,&bad,&stats)<0);free(a.map);free(expected.map);demo_frame_free(&f);cases++;}printf("SCANOUT_RGB24_BGRA_EXACT_BYTES_STRIDE_FORMAT_MARGINS_TAIL_COUNTERS_PASS cases=%u HOST_NOT_DP\n",cases);return 0;}
